style.css:
/* Roblox background image */
body {
    background-image: url("https://www.deviantart.com/drplaga049/art/Jane-Doe-Wallpaper-Selective-Coloring-1094336783");
    background-size: cover;       /* Makes it fill the screen */
    background-position: center;  /* Centers the image */
    background-repeat: no-repeat; /* Prevents tiling */
    background-attachment: fixed; /* Stays in place when scrolling */
}
